  const fnkDurumUyar = h => F.durum === '' || (F.durum === 'bekliyor' ? h.durum !== 'Onaylandı' : F.durum === 'onayli' ? h.durum === 'Onaylandı' : F.durum === 'sapYok' ? !h.sap : F.durum === 'sapVar' ? !!h.sap : F.durum === 'naYok' ? !h.nakitAkis && !nakitDisi(h) : F.durum === 'naVar' ? !!h.nakitAkis : false);
