      const ortakBas = `<td>${i + 1}</td><td>${tarih(r.tarih)}</td><td class="sol">${esc(r.sirket)}</td>`, ortakSon = `<td class="para g">${r.borc ? tutarH(r, r.borc) : ''}</td><td class="para c">${r.alacak ? tutarH(r, r.alacak) : ''}</td>`;
